import { Suspense } from "react";
import type { Metadata, Viewport } from "next";
import OptionsWorkspaceMount from "@/components/mounts/OptionsWorkspaceMount";
import OptionsPaywall from "@/components/OptionsPaywall";
import OptionsServiceUnavailable from "@/components/OptionsServiceUnavailable";
import { getLiveOptionsAccess } from "@/lib/entitlement";

// Options workspace (Wave-3 IA) — the options-intelligence hub, renamed from the
// former Research page. Serves /options under the (shell) route group (route groups
// don't affect the path); the shared chrome comes from app/(shell)/layout.tsx. This
// is the ex-/flow OptionsHubView engine, driven by the page-level WorkspaceTabs
// (see OptionsWorkspace). The old Fundamentals chip has moved to /analysis.
//
// All data is fetched CLIENT-side by the hub (flowGet, ~25s SWR), so there is no
// server payload to cache — the page is a thin server shell. The (shell) layout
// reads auth cookies (auto-dynamic); this page adds nothing server-side.

export const metadata: Metadata = { title: "Options · Mastermind Terminal" };

// Options research must support magnification. Explicitly clear the root chart
// viewport's maximum scale while inheriting its width and safe-area settings.
export const viewport: Viewport = {
  maximumScale: undefined,
  userScalable: true,
};

export default async function OptionsPage() {
  // Live options is a PAID surface (the `terminal_live_options` entitlement — the
  // same gate as /api/flow). Non-entitled callers get the upgrade paywall instead
  // of a would-be-empty workspace (the data API already 403s). The entitlement
  // read (auth cookies via billingAuth) forces per-request dynamic rendering.
  // FLOW_FIXTURE=1 (dev/CI) is exempt, mirroring /api/flow — fixture sessions
  // preview the workspace without auth; the var is never set in prod.
  if (process.env.FLOW_FIXTURE !== "1") {
    const access = await getLiveOptionsAccess();
    if (access === "denied") return <OptionsPaywall />;
    if (access === "unavailable") return <OptionsServiceUnavailable />;
  }
  // Suspense: OptionsWorkspace reads useSearchParams (?tab= deep-link seeding).
  // This route is always dynamically rendered today (force-dynamic (shell)
  // layout + the entitlement read above), so the params resolve server-side and
  // the boundary never suspends — it exists so a future rendering-mode change
  // degrades to a CSR bailout here instead of a build error.
  return (
    <Suspense fallback={null}>
      <OptionsWorkspaceMount />
    </Suspense>
  );
}

"use client";

// Shown at /options when the caller lacks the `terminal_live_options` entitlement
// (options/page.tsx gates server-side via hasLiveOptions). The data API already
// 403s, so this replaces the would-be-empty workspace with a clear upgrade prompt.
// Matches the locked v5 idiom — panel/line tokens + the brand-blue accent
// (--brand / --brand-2, the app's primary action colour). Bilingual via LEX t().
import { useOnboarding } from "@/components/onboarding/OnboardingProvider";
import { useT } from "@/lib/i18n";

export default function OptionsPaywall() {
  const t = useT();
  const onboarding = useOnboarding();
  const features = [t("opwF1"), t("opwF2"), t("opwF3"), t("opwF4")];
  return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "center", minHeight: "100%", padding: "48px 20px" }}>
      <div style={{ maxWidth: 440, width: "100%", background: "var(--panel-3)", border: "1px solid var(--line-3)", borderRadius: "var(--r-md)", padding: "26px 24px", textAlign: "center", boxShadow: "0 16px 48px -18px rgba(0,0,0,.7)" }}>
        <div style={{ fontSize: 11, letterSpacing: ".1em", textTransform: "uppercase", color: "var(--brand-2)", fontWeight: 700, marginBottom: 12 }}>{t("opwPlans")}</div>
        <h1 style={{ fontSize: 20, fontWeight: 750, color: "var(--text)", margin: "0 0 8px", lineHeight: 1.25 }}>{t("opwTitle")}</h1>
        <p style={{ fontSize: 13, lineHeight: 1.55, color: "var(--text)", opacity: 0.68, margin: "0 0 20px" }}>{t("opwBody")}</p>
        <ul style={{ listStyle: "none", padding: 0, margin: "0 0 22px", display: "grid", gap: 9, textAlign: "left" }}>
          {features.map((f, i) => (
            <li key={i} style={{ display: "flex", alignItems: "center", gap: 10, fontSize: 12.5, color: "var(--text)" }}>
              <span aria-hidden="true" style={{ color: "var(--brand-2)", flex: "none", fontSize: 11 }}>✦</span>
              {f}
            </li>
          ))}
        </ul>
        <button
          type="button"
          onClick={() => onboarding.open("signup", { plan: "essential" })}
          style={{ width: "100%", padding: "11px 16px", background: "var(--brand)", color: "#fff", border: "none", borderRadius: "var(--r-md)", fontSize: 13.5, fontWeight: 700, cursor: "pointer" }}
        >{t("opwCta")}</button>
        <p style={{ fontSize: 11.5, color: "var(--text)", opacity: 0.5, margin: "12px 0 0" }}>{t("opwSub")}</p>
      </div>
    </div>
  );
}

"use client";

import { useLang, type Lang } from "@/lib/i18n";
import { BrandMark } from "@/components/BrandMark";

/** Local bilingual copy avoids changing the globally evidence-locked shell LEX. */
function pick(lang: Lang, en: string, zh: string): string {
  return lang === "zh" ? zh : en;
}

/** An entitlement-provider outage is not a subscription downgrade. No data or
 * workspace is rendered on uncertainty; users can retry without a billing flow. */
export default function OptionsServiceUnavailable() {
  const { lang } = useLang();
  return (
    <main className="center" role="status" data-options-access="temporarily-unavailable">
      <div className="hero">
        <div className="mk"><BrandMark size={48} /></div>
        <h1 style={{ fontSize: 22, marginBottom: 8 }}>
          {pick(lang, "Options is temporarily unavailable", "期权服务暂时不可用")}
        </h1>
        <p className="tag" style={{ marginBottom: 20 }}>
          {pick(lang, "We couldn't verify Options access right now. This does not mean your subscription changed. Please retry.", "暂时无法验证访问权限。您的订阅状态尚未改变，请稍后重试。")}
        </p>
        <div className="cta">
          <button className="btn btn-primary" type="button" onClick={() => window.location.reload()}>
            {pick(lang, "Try again", "重试")}
          </button>
          <a className="btn btn-ghost" href="/terminal">{pick(lang, "Go to chart", "返回图表")}</a>
        </div>
      </div>
    </main>
  );
}

export type LiveOptionsAccess = "allowed" | "denied" | "unavailable";

export async function getLiveOptionsAccess(): Promise<LiveOptionsAccess> {
  const result = await fetchEntitlementCached(LIVE_OPTIONS);
  if (result.status !== "ok") return result.status;
  return LIVE_OPTIONS.ok(result.ent) ? "allowed" : "denied";
}

/** Shared read-access predicate; the server still authenticates and checks the authority.
 * Paid tier alone is not sufficient. The private unlimited overlay is the one exact exception.
 */
export function optionsReadAccess(entitlement: { tier?: unknown; features?: unknown } | null | undefined): boolean {
  if (!entitlement) return false;
  return (Array.isArray(entitlement.features) && entitlement.features.includes("terminal_live_options"))
    || (typeof entitlement.tier === "string" && entitlement.tier.trim().toLowerCase() === "unlimited");
}
